window.clampAspectCropToBounds = clampAspectCropToBounds;
window.cropRatioFromPreset = cropRatioFromPreset;
window.syncCropRatioButtons = syncCropRatioButtons;
window.fitCropRectToAspect = fitCropRectToAspect;
window.setCropAspectPreset = setCropAspectPreset;
window.resetCropBox = resetCropBox;
window.applyImageCrop = applyImageCrop;
window.uploadCroppedBlob = uploadCroppedBlob;
